    private final TextField itemField;
    private final UnorderedList itemList;
    private final Span countLabel;

    ItemsView() {
        itemField = new TextField("Item");

        var addButton = new Button("Add", event -> addItem());
        addButton.addThemeVariants(ButtonVariant.PRIMARY);
        var clearButton = new Button("Clear", event -> clearItems());

        var form = new HorizontalLayout(itemField, addButton, clearButton);
        form.setAlignItems(FlexComponent.Alignment.END);

        itemList = new UnorderedList();
        countLabel = new Span();
        updateCount();

        add(new H1("Items"), form, countLabel, itemList);
    }

    private void addItem() {
        var text = itemField.getValue();
        if (text.isBlank()) {
            itemField.setInvalid(true);
            itemField.setErrorMessage("Item is required");
            return;
        }
        itemList.add(new ListItem(text));
        itemField.clear();
        itemField.setInvalid(false);
        updateCount();
    }

    private void clearItems() {
        itemList.removeAll();
        updateCount();
    }

    private void updateCount() {
        countLabel.setText("Items: " + itemList.getChildren().count());
    }
